package autonewsroller.video;

import autonewsroller.util.Text;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class CaptionWriter {private CaptionWriter(){}public static Path write(Path out,String narration,double duration,String mode)throws Exception{if("off".equalsIgnoreCase(mode))return null;List<String>units=new ArrayList<>();if("word".equalsIgnoreCase(mode)){for(String w:Text.clean(narration).split("\\s+"))if(!w.isBlank())units.add(w);}else units.addAll(Text.sentences(narration));if(units.isEmpty())units=List.of(narration);int total=units.stream().mapToInt(Text::words).sum();double t=0;StringBuilder s=new StringBuilder();for(int i=0;i<units.size();i++){String u=units.get(i);double d=i==units.size()-1?duration-t:Math.max(.15,duration*Math.max(1,Text.words(u))/Math.max(1,total));double end=Math.min(duration,t+d);s.append(i+1).append('\n').append(ts(t)).append(" --> ").append(ts(end)).append('\n').append(u).append("\n\n");t=end;}Files.writeString(out,s.toString(),StandardCharsets.UTF_8);return out;}private static String ts(double v){long ms=Math.max(0,Math.round(v*1000));long h=ms/3600000;ms%=3600000;long m=ms/60000;ms%=60000;long sec=ms/1000;ms%=1000;return String.format("%02d:%02d:%02d,%03d",h,m,sec,ms);}}
